#!/usr/bin/env python3
"""Generate lib/pg/src/pg/ui/font_data.cpp from pgfont.py (the mockups' glyph table).

    python3 tools/ux_mock/gen_font.py

FONT_S: 95 ASCII glyphs (0x20..0x7E), 5 column bytes each, bit 0 = top row,
bit 7 = descender row.  Icons: codes 0x80.. in pgfont.ICON_ORDER, same layout.
"""
import os
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)
import pgfont  # noqa: E402

OUT = os.path.join(HERE, "..", "..", "lib", "pg", "src", "pg", "ui", "font_data.cpp")


def main():
    lines = [
        "// GENERATED by tools/ux_mock/gen_font.py from tools/ux_mock/pgfont.py. Do not edit.",
        "#include \"font.h\"",
        "",
        "namespace pg {",
        "namespace ui {",
        "",
        "const uint8_t kFontS[kFontCount][5] = {",
    ]
    for i, g in enumerate(pgfont.GLYPHS):
        ch = chr(pgfont.FIRST + i)
        name = {"\\": "backslash", "'": "quote"}.get(ch, ch)
        lines.append("    {%s},  // %s" % (", ".join("0x%02X" % b for b in g), name))
    lines.append("};")
    lines.append("")
    lines.append("const uint8_t kFontIcons[kIconCount][5] = {")
    for i, name in enumerate(pgfont.ICON_ORDER):
        cols = pgfont.glyph_columns(chr(0x80 + i))
        lines.append("    {%s},  // 0x%02X %s" % (", ".join("0x%02X" % b for b in cols), 0x80 + i, name))
    lines.append("};")
    lines.append("")
    lines.append("}  // namespace ui")
    lines.append("}  // namespace pg")
    assert len(pgfont.GLYPHS) == 95
    with open(OUT, "w") as f:
        f.write("\n".join(lines) + "\n")
    print(os.path.relpath(OUT), "icons:", " ".join(pgfont.ICON_ORDER))


if __name__ == "__main__":
    main()
